rex.mode("repeat", { exclusive = true })
rex.bind("ctrl+a>ctrl+r", "client.mode.enter", { name = "repeat" })
rex.bind("repeat/enter", "client.mode.exit")
rex.bind("repeat/escape", "client.mode.exit")

rex.bind("ctrl+a>ctrl+a", "pane.send_key", { key = "ctrl+a" })
rex.bind("ctrl+a>c", "client.tab.new")
rex.bind("ctrl+a>n", "client.tab.next")
rex.bind("ctrl+a>p", "client.tab.previous")
rex.bind("ctrl+a>shift+n", "session.next")
rex.bind("repeat/shift+n", "session.next")
rex.bind("ctrl+a>shift+p", "session.previous")
rex.bind("repeat/shift+p", "session.previous")
rex.bind("ctrl+a>j", "session.switch")
rex.bind("ctrl+a>shift+j", "session.switch")
rex.bind("ctrl+a>shift+'", "pane.split", { direction = "down" })
rex.bind("ctrl+a>shift+5", "pane.split", { direction = "right" })
rex.bind("ctrl+a>x", "pane.close")
rex.bind("repeat/x", "pane.close")
rex.bind("ctrl+a>r", "client.config.reload")
rex.bind("ctrl+a>shift+,", "session.rename")
